/// <summary>
/// This <c>METShipmentCrMETShipmentPackingSlipCreateeate</c> class is used for shipment validation and packing slip creation.
/// </summary>
class METShipmentPackingSlipCreate
{
}

Method.Source:
/// <summary>
/// Constructs the instance for <c>METShipmentPackingSlipCreate</c> class.
/// </summary>
/// <returns>METShipmentPackingSlipCreate class instance.</returns>
public static METShipmentPackingSlipCreate construct()
{
    METShipmentPackingSlipCreate   shipmentPackingSlipCreate;

    shipmentPackingSlipCreate = new METShipmentPackingSlipCreate();

    return shipmentPackingSlipCreate;
}

/// <summary>
/// Shipment create validations
/// </summary>
public static void shipmentValidations(Map  _headerMap)
{
    METSalesOrderShipmentLoadHeader     mETSalesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadLines      mETSalesOrderShipmentLoadLinesLoc;
    METContainerTypeTable               mETContainerTypeTable;
    WMSPickingRoute                     wmsPickingRoute;
    boolean                             isUnMarkVal;
    MapIterator                         mapIterator = new MapIterator(_headerMap);

    while (mapIterator.more())
    {
        //print mapIterator.key();
        //print mapIterator.value();
        //mapIterator.next();

        mETSalesOrderShipmentLoadHeader = mETSalesOrderShipmentLoadHeader::findByRecId(mapIterator.key(), true);

        isUnMarkVal = false;

        select firstonly mETContainerTypeTable
            where mETContainerTypeTable.InventLocationId == mETSalesOrderShipmentLoadHeader.Warehouse;

        if (!mETContainerTypeTable)
        {
            Error(strFmt("@MET:METShipmentNotAssociated", mETSalesOrderShipmentLoadHeader.ShipmentId));
            isUnMarkVal = true;
        }

        //Need to throw error for all non valid shipment, hence while select. 
        while select mETSalesOrderShipmentLoadLinesLoc
            where mETSalesOrderShipmentLoadLinesLoc.shipmentid == metsalesordershipmentloadheader.ShipmentId
        {
            if (mETSalesOrderShipmentLoadLinesLoc.displayPickListStatus() != WMSExpeditionStatus::Complete)
            {
                error(strfmt("@met:metslnotfullypicked", mETSalesOrderShipmentLoadLinesLoc.OrderNum, mETSalesOrderShipmentLoadLinesLoc.ItemId));
                isunmarkval = true;
            }
        }

        METCustTable   custTableLoc = METCustTable::find(mETSalesOrderShipmentLoadHeader.CustAccount);

        if (custTableLoc.FinalizationDocument  == METFinalizationDocument::None)
        {
            warning(strFmt("@MET:ValidateFinizationDoc", mETSalesOrderShipmentLoadHeader.CustAccount, mETSalesOrderShipmentLoadHeader.ShipmentId));
        }

        //TODO - Check unmark
        //if (isUnMarkVal)
        //{
        //    METShipmentPackingSlipCreate::unmarkAllFromLoad(mETSalesOrderShipmentLoadHeader.LoadId);
        //    mETSalesOrderShipmentLoadHeader.reread();
        //}

        mapIterator.next();
    }
}

/// <summary>
/// Create a packing slip process
/// </summary>
public static void createPackingSlip(Map        _headerMarkedMap)
{
    MapIterator                         mapIterator = new MapIterator(_headerMarkedMap);
    //Query                               query;
    //QueryRun                            qr;
    //QueryBuildDataSource                qbds;
    //QueryBuildRange                     qbr;
    METSalesOrderShipmentLoadHeader     mETSalesOrderShipmentLoadHeader;
    container                           conShipmentId, conDocStatus, conAccountOrder;

    //query   = new Query();
    //qbds    = query.addDataSource(tableNum(METSalesOrderShipmentLoadHeader));
    ////Set the Range and Range value
    //qbr     = qbds.addRange(fieldNum(METSalesOrderShipmentLoadHeader, MarkSelection));
    //qbr.value(enum2str(NoYes::Yes));

    //qr      = new QueryRun(query);

    while (mapIterator.more())
    {
        mETSalesOrderShipmentLoadHeader = mETSalesOrderShipmentLoadHeader::findByRecId(mapIterator.key(), true);

        ttsbegin;
        mETSalesOrderShipmentLoadHeader.selectForUpdate(true);
        mETSalesOrderShipmentLoadHeader.ShipmentStatus = MetShipmentStatus::Loaded;
        mETSalesOrderShipmentLoadHeader.LoadStatus     = MetLoadStatus::Loaded;
        mETSalesOrderShipmentLoadHeader.update();
        ttscommit;

        METCustTable       custTableLoc = METCustTable::find(mETSalesOrderShipmentLoadHeader.CustAccount);

        if(custTableLoc.FinalizationDocument != METFinalizationDocument::None)
        {
            DocumentStatus      docStatus       = custTableLoc.FinalizationDocument == METFinalizationDocument::Invoice ? DocumentStatus::Invoice : DocumentStatus::PackingSlip;
            AccountOrder        accountOrder    = mETSalesOrderShipmentLoadHeader.PostMultiDocument == NoYes::No ? AccountOrder::Account : AccountOrder::None;

            conShipmentId   += mETSalesOrderShipmentLoadHeader.ShipmentId;
            conDocStatus    += docStatus;
            conAccountOrder += accountOrder;
        }

        mapIterator.next();
    }
    //Create a packing slip
    METShipmentPackingSlipCreate::postSalesDocument(conShipmentId, conDocStatus, conAccountOrder);
}

/// <summary>
/// Post the sales packing slip
/// </summary>
/// <param name = "_conShipmentId">ShipmentID</param>
/// <param name = "_conDocStatus">DocumentStatus</param>
public static void postSalesDocument(container _conShipmentId, container _conDocStatus, container _conAccountOrder)
{
    METSalesDocumentPostingDataContract     contract = new METSalesDocumentPostingDataContract();
    contract.parmShipmentIdList(_conShipmentId);
    contract.parmDocStatusList(_conDocStatus);
    contract.parmAccountOrderList(_conAccountOrder);

    METSalesDocumentPostingService          service = new METSalesDocumentPostingService();
    service.run(contract);
}
